. "$PSScriptRoot\scripts\windows-common.ps1"
$container = if ($env:GROKBOT_COMPUTER_CONTAINER) { $env:GROKBOT_COMPUTER_CONTAINER } else { 'grokbot-computer' }
$image = if ($env:GROKBOT_COMPUTER_IMAGE) { $env:GROKBOT_COMPUTER_IMAGE } else { 'public.ecr.aws/k0i0n2g5/cursorenvironments/universal@sha256:dcac90cba36653f261988b1c88d11b7655493d455c4af0a18c5991ddaa5da020' }
function Require-Docker { if (-not (Get-Command docker -ErrorAction SilentlyContinue)) { throw 'Docker Desktop is required.' }; & cmd.exe /d /c 'docker info >nul 2>nul'; if ($LASTEXITCODE) { throw 'Docker Desktop daemon is not available.' } }
function Ready { return (Test-HttpHealth 'http://127.0.0.1:6080/vnc.html') -and (Test-HttpHealth 'http://127.0.0.1:1337/health') }
function Start-Computer { Require-Docker; docker container inspect $container *> $null; if ($LASTEXITCODE -eq 0) { docker start $container *> $null } else { docker pull $image; docker run -d --name $container --restart unless-stopped --shm-size=1g -p 127.0.0.1:1337:1337 -p 127.0.0.1:1338:1338 -p 127.0.0.1:1339:1339 -p 127.0.0.1:6080:6080 -p 127.0.0.1:6081:6081 -v grokbot-computer-workspace:/workspace -v grokbot-computer-chrome:/home/box/chrome-profile -v grokbot-computer-data:/home/box/sand-data $image *> $null }; for ($i = 0; $i -lt 120; $i++) { if (Ready) { Write-Host 'computer ready: http://127.0.0.1:6080/vnc.html'; return }; Start-Sleep -Milliseconds 500 }; throw 'Computer did not become ready.' }
Require-Docker
switch ($args[0]) { 'start' { Start-Computer } 'restart' { docker rm -f $container *> $null; Start-Computer } 'stop' { docker stop $container *> $null; Write-Host "computer stopped: $container" } 'logs' { docker logs --tail 200 $container } 'open' { Start-Process 'http://127.0.0.1:6080/vnc.html' } 'status' { if (Ready) { Write-Host "computer ready: $container" } else { Write-Host "computer not ready: $container"; exit 1 } } default { Write-Host 'usage: .\computerctl.ps1 {start|stop|restart|status|logs|open}'; exit 2 } }
